    scalar(c, ScriptTables.subscripts["i" as Character], 0x1D62, "LATIN SUBSCRIPT SMALL LETTER I")
    scalar(c, ScriptTables.subscripts["j" as Character], 0x2C7C, "LATIN SUBSCRIPT SMALL LETTER J")
    scalar(c, ScriptTables.subscripts["k" as Character], 0x2096, "LATIN SUBSCRIPT SMALL LETTER K")
    scalar(c, ScriptTables.subscripts["l" as Character], 0x2097, "LATIN SUBSCRIPT SMALL LETTER L")
    scalar(c, ScriptTables.subscripts["m" as Character], 0x2098, "LATIN SUBSCRIPT SMALL LETTER M")
    scalar(c, ScriptTables.subscripts["n" as Character], 0x2099, "LATIN SUBSCRIPT SMALL LETTER N")
    scalar(c, ScriptTables.subscripts["o" as Character], 0x2092, "LATIN SUBSCRIPT SMALL LETTER O")
    scalar(c, ScriptTables.subscripts["p" as Character], 0x209A, "LATIN SUBSCRIPT SMALL LETTER P")
    scalar(c, ScriptTables.subscripts["r" as Character], 0x1D63, "LATIN SUBSCRIPT SMALL LETTER R")
    scalar(c, ScriptTables.subscripts["s" as Character], 0x209B, "LATIN SUBSCRIPT SMALL LETTER S")
    scalar(c, ScriptTables.subscripts["t" as Character], 0x209C, "LATIN SUBSCRIPT SMALL LETTER T")
    scalar(c, ScriptTables.subscripts["u" as Character], 0x1D64, "LATIN SUBSCRIPT SMALL LETTER U")
    scalar(c, ScriptTables.subscripts["v" as Character], 0x1D65, "LATIN SUBSCRIPT SMALL LETTER V")
    scalar(c, ScriptTables.subscripts["x" as Character], 0x2093, "LATIN SUBSCRIPT SMALL LETTER X")

    // MARK: Radicals
    scalar(c, ScriptTables.radicals[2], 0x221A, "SQUARE ROOT")
    scalar(c, ScriptTables.radicals[3], 0x221B, "CUBE ROOT")
    scalar(c, ScriptTables.radicals[4], 0x221C, "FOURTH ROOT")

    // MARK: Table sizes — a dropped entry must fail, not pass quietly.
    c.equal(SymbolTable.symbols.count, 202, "symbol count")
    c.equal(ScriptTables.superscripts.count, 40, "superscript count")
    c.equal(ScriptTables.subscripts.count, 32, "subscript count")
}

private func scalar(_ c: Checker, _ actual: String?, _ expected: [UInt32], _ name: String,
                    file: StaticString = #filePath, line: UInt = #line) {
    guard let actual else { return c.fail("missing entry for \(name)", file: file, line: line) }
    c.equal(actual.unicodeScalars.map(\.value), expected, name, file: file, line: line)
}

private func scalar(_ c: Checker, _ actual: Character?, _ expected: UInt32, _ name: String,
                    file: StaticString = #filePath, line: UInt = #line) {
    guard let actual else { return c.fail("missing entry for \(name)", file: file, line: line) }
    c.equal(actual.unicodeScalars.map(\.value), [expected], name, file: file, line: line)
}
